// File name: projects/05/Memory.hdl

/**
 * The complete address space of the Hack computer's memory,
 * including RAM and memory-mapped I/O. 
 * The chip facilitates read and write operations, as follows:
 *     Read:  out(t) = Memory[address(t)](t)
 *     Write: if load(t-1) then Memory[address(t-1)](t) = in(t-1)
 * In words: the chip always outputs the value stored at the memory 
 * location specified by address. If load==1, the in value is loaded 
 * into the memory location specified by address. This value becomes 
 * available through the out output from the next time step onward.
 * Address space rules:
 * Only the upper 16K+8K+1 words of the Memory chip are used. 
 * Access to address>0x6000 is invalid. Access to any address in 
 * the range 0x4000-0x5FFF results in accessing the screen memory 
 * map. Access to address 0x6000 results in accessing the keyboard 
 * memory map. The behavior in these addresses is described in the 
 * Screen and Keyboard chip specifications given in the book.
 */

CHIP Memory {
    IN in[16], load, address[15];
    OUT out[16];

    PARTS:
    // Address decode (2-bit sel for DMux4Way / Mux4Way16):
    //   address[14]=0                 -> 00 -> RAM      (0x0000-0x3FFF)
    //   address[14]=1, address[13]=0  -> 01 -> Screen   (0x4000-0x5FFF)
    //   address[14]=1, address[13]=1  -> 10 -> Keyboard (0x6000, read-only)
    Not(in=address[13], out=notA13);
    And(a=address[14], b=notA13, out=sel0);
    And(a=address[14], b=address[13], out=sel1);

    DMux4Way(in=load, sel[0]=sel0, sel[1]=sel1, a=loadRam, b=loadScreen);

    RAM16K(in=in, load=loadRam, address=address[0..13], out=ramOut);
    Screen(in=in, load=loadScreen, address=address[0..12], out=screenOut);
    Keyboard(out=kbdOut);

    Mux4Way16(a=ramOut, b=screenOut, c=kbdOut, d=false,
              sel[0]=sel0, sel[1]=sel1, out=out);
}// This file is part of www.nand2tetris.org
// and the book "The Elements of Computing Systems"
// by Nisan and Schocken, MIT Press.
// File name: projects/05/CPU.hdl

/**
 * The Hack CPU (Central Processing unit), consisting of an ALU,
 * two registers named A and D, and a program counter named PC.
 * The CPU is designed to fetch and execute instructions written in 
 * the Hack machine language. In particular, functions as follows:
 * Executes the inputted instruction according to the Hack machine 
 * language specification. The D and A in the language specification
 * refer to CPU-resident registers, while M refers to the external
 * memory location addressed by A, i.e. to Memory[A]. The inM input 
 * holds the value of this location. If the current instruction needs 
 * to write a value to M, the value is placed in outM, the address 
 * of the target location is placed in the addressM output, and the 
 * writeM control bit is asserted. (When writeM==0, any value may 
 * appear in outM). The outM and writeM outputs are combinational: 
 * they are affected instantaneously by the execution of the current 
 * instruction. The addressM and pc outputs are clocked: although they 
 * are affected by the execution of the current instruction, they commit 
 * to their new values only in the next time step. If reset==1 then the 
 * CPU jumps to address 0 (i.e. pc is set to 0 in next time step) rather 
 * than to the address resulting from executing the current instruction. 
 */

CHIP CPU {

    IN  inM[16],         // M value input  (M = contents of RAM[A])
        instruction[16], // Instruction for execution
        reset;           // Signals whether to re-start the current
                         // program (reset==1) or continue executing
                         // the current program (reset==0).

    OUT outM[16],        // M value output
        writeM,          // Write to M? 
        addressM[15],    // Address in data memory (of M)
        pc[15];          // address of next instruction

    PARTS:
    // A-register input: A-instruction -> instruction, C-instruction -> ALU out
    Mux16(a=instruction, b=aluOut, sel=instruction[15], out=aRegIn);

    // A-register load: A-instruction, or C-instruction with d1
    And(a=instruction[15], b=instruction[5], out=loadAc);
    Or(a=loadAc, b=notInst15, out=loadA);
    Not(in=instruction[15], out=notInst15);

    ARegister(in=aRegIn, load=loadA, out=aRegOut, out[0..14]=addressM);

    // ALU y input: A or M, selected by the a-bit (instruction[12])
    Mux16(a=aRegOut, b=inM, sel=instruction[12], out=aluY);

    // D-register load: C-instruction with d2
    And(a=instruction[15], b=instruction[4], out=loadD);
    DRegister(in=aluOut, load=loadD, out=dRegOut);

    // ALU
    ALU(x=dRegOut, y=aluY,
        zx=instruction[11], nx=instruction[10],
        zy=instruction[9],  ny=instruction[8],
        f=instruction[7],   no=instruction[6],
        out=aluOut, out=outM, zr=zr, ng=ng);

    // writeM: C-instruction with d3
    And(a=instruction[15], b=instruction[3], out=writeM);

    // Jump logic from zr, ng and jump bits j1,j2,j3
    Not(in=zr, out=notZr);
    Not(in=ng, out=notNg);
    And(a=notZr, b=notNg, out=pos);       // out > 0
    And(a=instruction[0], b=pos, out=jgt); // JGT
    And(a=instruction[1], b=zr, out=jeq);  // JEQ
    And(a=instruction[2], b=ng, out=jlt);  // JLT
    Or(a=jgt, b=jeq, out=jgtEq);
    Or(a=jgtEq, b=jlt, out=jump);
    And(a=jump, b=instruction[15], out=loadPc);

    PC(in=aRegOut, load=loadPc, inc=true, reset=reset, out[0..14]=pc);
}// This file is part of www.nand2tetris.org
// and the book "The Elements of Computing Systems"
// by Nisan and Schocken, MIT Press.
// File name: projects/05/Computer.hdl

/**
 * The HACK computer, including CPU, ROM and RAM.
 * When reset is 0, the program stored in the computer's ROM executes.
 * When reset is 1, the execution of the program restarts. 
 * Thus, to start a program's execution, reset must be pushed "up" (1)
 * and "down" (0). From this point onward the user is at the mercy of 
 * the software. In particular, depending on the program's code, the 
 * screen may show some output and the user may be able to interact 
 * with the computer via the keyboard.
 */

CHIP Computer {

    IN reset;

    PARTS:
    ROM32K(address=pc, out=instruction);

    CPU(inM=inM, instruction=instruction, reset=reset,
        outM=outM, writeM=writeM, addressM=addressM, pc=pc);

    Memory(in=outM, load=writeM, address=addressM, out=inM);
}

