// Runs an infinite loop that listens to the keyboard input.
// When a key is pressed (any key), the program blackens the screen,
// i.e. writes "black" in every pixel;
// the screen should remain fully black as long as the key is pressed. 
// When no key is pressed, the program clears the screen, i.e. writes
// "white" in every pixel;
// the screen should remain fully clear as long as no key is pressed.

// Infinite loop: poll KBD, then repaint the entire screen.

(MAIN)
	// Decide the fill color based on keyboard input
	@KBD
	D=M
	@WHITE
	D;JEQ          // no key pressed -> white

	// Key pressed -> black
	@color
	M=-1
	@FILL
	0;JMP

(WHITE)
	@color
	M=0

(FILL)
	// addr = SCREEN, count = 8192
	@SCREEN
	D=A
	@addr
	M=D
	@8192
	D=A
	@count
	M=D

(LOOP)
	// If count == 0, repaint is done; poll the keyboard again
	@count
	D=M
	@MAIN
	D;JEQ

	// RAM[addr] = color
	@color
	D=M
	@addr
	A=M
	M=D

	// addr++, count--
	@addr
	M=M+1
	@count
	M=M-1

	@LOOP
	0;JMP

