"""Minimal nand2tetris HDL simulator with behavioral built-in chips.

Mirrors the official HardwareSimulator's chip resolution: HDL files are
looked up in the given search directories; anything not found falls back
to a built-in (behavioral) implementation.  Used to verify the project
HDL files without a Java toolchain.
"""

import os
import re

MASK16 = 0xFFFF


# ---------------------------------------------------------------- parsing

def _strip_comments(text):
    text = re.sub(r"/\*.*?\*/", "", text, flags=re.S)
    return re.sub(r"//[^\n]*", "", text)


def _parse_pin_ref(s):
    """'name', 'name[i]' or 'name[i..j]' -> (name, lo, hi, explicit)."""
    m = re.match(r"^(\w+)(?:\[(\d+)(?:\.\.(\d+))?\])?$", s.strip())
    if not m:
        raise ValueError("bad pin ref: %r" % s)
    name = m.group(1)
    if m.group(2) is None:
        return name, 0, 0, False
    lo = int(m.group(2))
    hi = int(m.group(3)) if m.group(3) else lo
    return name, lo, hi, True


class ChipDef:
    def __init__(self, name, inputs, outputs, parts):
        self.name = name
        self.inputs = inputs      # name -> width
        self.outputs = outputs    # name -> width
        self.parts = parts        # [(chip_name, [(pin_ref, expr)])]


def parse_hdl(path):
    text = _strip_comments(open(path).read())
    m = re.search(r"CHIP\s+(\w+)\s*\{(.*)\}\s*$", text, re.S)
    if not m:
        raise ValueError("no CHIP block in %s" % path)
    name, body = m.group(1), m.group(2)
    idx = body.index("PARTS")
    header, parts_sec = body[:idx], body[idx + len("PARTS"):]
    parts_sec = parts_sec.lstrip()
    if parts_sec.startswith(":"):
        parts_sec = parts_sec[1:]

    inputs, outputs = {}, {}
    for kind, lst in re.findall(r"\b(IN|OUT)\s+(.*?);", header, re.S):
        for item in lst.split(","):
            item = item.strip()
            if not item:
                continue
            pm = re.match(r"^(\w+)(?:\[(\d+)\])?$", item)
            d = inputs if kind == "IN" else outputs
            d[pm.group(1)] = int(pm.group(2)) if pm.group(2) else 1

    parts = []
    for stmt in parts_sec.split(";"):
        stmt = stmt.strip()
        if not stmt:
            continue
        pm = re.match(r"^(\w+)\s*\((.*)\)\s*$", stmt, re.S)
        if not pm:
            raise ValueError("bad part statement %r in %s" % (stmt, path))
        conns = []
        for a in pm.group(2).split(","):
            a = a.strip()
            if not a:
                continue
            lhs, rhs = a.split("=")
            conns.append((_parse_pin_ref(lhs), rhs.strip()))
        parts.append((pm.group(1), conns))
    return ChipDef(name, inputs, outputs, parts)


# ---------------------------------------------------------------- builtins

def _alu(x, y, zx, nx, zy, ny, f, no):
    if zx:
        x = 0
    if nx:
        x ^= MASK16
    if zy:
        y = 0
    if ny:
        y ^= MASK16
    out = ((x + y) & MASK16) if f else (x & y)
    if no:
        out ^= MASK16
    zr = 1 if out == 0 else 0
    ng = (out >> 15) & 1
    return out, zr, ng


class Builtin:
    """Behavioral built-in chip instance."""

    def __init__(self, name):
        self.name = name
        self.state = 0
        self.pending = None
        size = {"RAM8": 8, "RAM64": 64, "RAM512": 512, "RAM4K": 4096,
                "RAM16K": 16384, "Screen": 8192}.get(name)
        self.mem = [0] * size if size else None
        self.kbd = 0               # Keyboard
        self.program = []          # ROM32K

    # -- combinational evaluation (records clocked pending state) --
    def eval(self, inp):
        n = self.name
        g = lambda k: inp.get(k, 0)
        if n == "Nand":
            return {"out": 1 - (g("a") & g("b"))}
        if n == "Not":
            return {"out": 1 - g("in")}
        if n == "And":
            return {"out": g("a") & g("b")}
        if n == "Or":
            return {"out": g("a") | g("b")}
        if n == "Xor":
            return {"out": g("a") ^ g("b")}
        if n == "Mux":
            return {"out": g("b") if g("sel") else g("a")}
        if n == "DMux":
            return {"a": g("in") & (1 - g("sel")), "b": g("in") & g("sel")}
        if n == "Not16":
            return {"out": g("in") ^ MASK16}
        if n == "And16":
            return {"out": g("a") & g("b")}
        if n == "Or16":
            return {"out": g("a") | g("b")}
        if n == "Mux16":
            return {"out": g("b") if g("sel") else g("a")}
        if n == "Or8Way":
            return {"out": 1 if g("in") else 0}
        if n == "Mux4Way16":
            sel = g("sel")
            return {"out": (g("a"), g("b"), g("c"), g("d"))[sel]}
        if n == "Mux8Way16":
            sel = g("sel")
            return {"out": (g("a"), g("b"), g("c"), g("d"),
                            g("e"), g("f"), g("g"), g("h"))[sel]}
        if n == "DMux4Way":
            sel = g("sel")
            r = {"a": 0, "b": 0, "c": 0, "d": 0}
            r["abcd"[sel]] = g("in")
            return r
        if n == "DMux8Way":
            sel = g("sel")
            r = {k: 0 for k in "abcdefgh"}
            r["abcdefgh"[sel]] = g("in")
            return r
        if n == "HalfAdder":
            s = g("a") + g("b")
            return {"sum": s & 1, "carry": (s >> 1) & 1}
        if n == "FullAdder":
            s = g("a") + g("b") + g("c")
            return {"sum": s & 1, "carry": (s >> 1) & 1}
        if n == "Add16":
            return {"out": (g("a") + g("b")) & MASK16}
        if n == "Inc16":
            return {"out": (g("in") + 1) & MASK16}
        if n == "ALU":
            out, zr, ng = _alu(g("x"), g("y"), g("zx"), g("nx"),
                               g("zy"), g("ny"), g("f"), g("no"))
            return {"out": out, "zr": zr, "ng": ng}
        if n == "DFF":
            self.pending = g("in")
            return {"out": self.state}
        if n in ("ARegister", "DRegister", "Register"):
            self.pending = g("in") if g("load") else self.state
            return {"out": self.state}
        if n == "Bit":
            self.pending = g("in") if g("load") else self.state
            return {"out": self.state & 1}
        if n == "PC":
            if g("reset"):
                self.pending = 0
            elif g("load"):
                self.pending = g("in")
            elif g("inc"):
                self.pending = (self.state + 1) & MASK16
            else:
                self.pending = self.state
            return {"out": self.state}
        if n in ("RAM8", "RAM64", "RAM512", "RAM4K", "RAM16K", "Screen"):
            addr = g("address")
            if g("load"):
                self.pending = (addr, g("in"))
            else:
                self.pending = None
            return {"out": self.mem[addr]}
        if n == "Keyboard":
            return {"out": self.kbd}
        if n == "ROM32K":
            addr = g("address")
            return {"out": self.program[addr] if addr < len(self.program) else 0}
        raise ValueError("unknown builtin " + n)

    def commit(self):
        if self.name == "DFF":
            if self.pending is not None:
                self.state = self.pending & 1
        elif self.name in ("ARegister", "DRegister", "Register", "Bit", "PC"):
            if self.pending is not None:
                self.state = self.pending & MASK16
        elif self.mem is not None:
            if self.pending is not None:
                addr, val = self.pending
                self.mem[addr] = val & MASK16
        self.pending = None


BUILTIN_PINS = {
    "Nand": ({"a": 1, "b": 1}, {"out": 1}),
    "Not": ({"in": 1}, {"out": 1}),
    "And": ({"a": 1, "b": 1}, {"out": 1}),
    "Or": ({"a": 1, "b": 1}, {"out": 1}),
    "Xor": ({"a": 1, "b": 1}, {"out": 1}),
    "Mux": ({"a": 1, "b": 1, "sel": 1}, {"out": 1}),
    "DMux": ({"in": 1, "sel": 1}, {"a": 1, "b": 1}),
    "Not16": ({"in": 16}, {"out": 16}),
    "And16": ({"a": 16, "b": 16}, {"out": 16}),
    "Or16": ({"a": 16, "b": 16}, {"out": 16}),
    "Mux16": ({"a": 16, "b": 16, "sel": 1}, {"out": 16}),
    "Or8Way": ({"in": 8}, {"out": 1}),
    "Mux4Way16": ({"a": 16, "b": 16, "c": 16, "d": 16, "sel": 2}, {"out": 16}),
    "Mux8Way16": ({"a": 16, "b": 16, "c": 16, "d": 16, "e": 16, "f": 16,
                   "g": 16, "h": 16, "sel": 3}, {"out": 16}),
    "DMux4Way": ({"in": 1, "sel": 2}, {"a": 1, "b": 1, "c": 1, "d": 1}),
    "DMux8Way": ({"in": 1, "sel": 3},
                 {"a": 1, "b": 1, "c": 1, "d": 1, "e": 1, "f": 1, "g": 1, "h": 1}),
    "HalfAdder": ({"a": 1, "b": 1}, {"sum": 1, "carry": 1}),
    "FullAdder": ({"a": 1, "b": 1, "c": 1}, {"sum": 1, "carry": 1}),
    "Add16": ({"a": 16, "b": 16}, {"out": 16}),
    "Inc16": ({"in": 16}, {"out": 16}),
    "ALU": ({"x": 16, "y": 16, "zx": 1, "nx": 1, "zy": 1, "ny": 1,
             "f": 1, "no": 1}, {"out": 16, "zr": 1, "ng": 1}),
    "DFF": ({"in": 1}, {"out": 1}),
    "Bit": ({"in": 1, "load": 1}, {"out": 1}),
    "ARegister": ({"in": 16, "load": 1}, {"out": 16}),
    "DRegister": ({"in": 16, "load": 1}, {"out": 16}),
    "Register": ({"in": 16, "load": 1}, {"out": 16}),
    "PC": ({"in": 16, "load": 1, "inc": 1, "reset": 1}, {"out": 16}),
    "RAM8": ({"in": 16, "load": 1, "address": 3}, {"out": 16}),
    "RAM64": ({"in": 16, "load": 1, "address": 6}, {"out": 16}),
    "RAM512": ({"in": 16, "load": 1, "address": 9}, {"out": 16}),
    "RAM4K": ({"in": 16, "load": 1, "address": 12}, {"out": 16}),
    "RAM16K": ({"in": 16, "load": 1, "address": 14}, {"out": 16}),
    "Screen": ({"in": 16, "load": 1, "address": 13}, {"out": 16}),
    "Keyboard": ({}, {"out": 16}),
    "ROM32K": ({"address": 15}, {"out": 16}),
}


# ---------------------------------------------------------------- composite

class ChipLoader:
    def __init__(self, dirs):
        self.dirs = dirs
        self.defs = {}

    def get_def(self, name):
        if name in self.defs:
            return self.defs[name]
        for d in self.dirs:
            p = os.path.join(d, name + ".hdl")
            if os.path.exists(p):
                cdef = parse_hdl(p)
                self.defs[name] = cdef
                return cdef
        self.defs[name] = None
        return None

    def instantiate(self, name):
        cdef = self.get_def(name)
        if cdef is None:
            if name not in BUILTIN_PINS:
                raise ValueError("no HDL or builtin for chip " + name)
            return Builtin(name)
        return Composite(cdef, self)


def pin_maps(name, loader):
    """Return (inputs, outputs) pin-width maps for any chip."""
    cdef = loader.get_def(name)
    if cdef is None:
        return BUILTIN_PINS[name]
    return cdef.inputs, cdef.outputs


class Composite:
    def __init__(self, cdef, loader):
        self.cdef = cdef
        self.name = cdef.name
        self.parts = []          # [(inst, in_sinks, out_drivers)]
        # in_sinks: (pin, pbit) -> ('const', v) | ('wire', wname, wbit)
        # drivers:  (wname, wbit) -> (part_idx, pin, pbit)
        self.drivers = {}
        for pidx, (pname, conns) in enumerate(cdef.parts):
            inst = loader.instantiate(pname)
            p_in, p_out = pin_maps(pname, loader)
            sinks = {}
            for (pin, plo, phi, pexp), rhs in conns:
                if pin in p_out:
                    pwidth = p_out[pin]
                elif pin in p_in:
                    pwidth = p_in[pin]
                else:
                    raise ValueError("%s: chip %s has no pin %s" %
                                     (cdef.name, pname, pin))
                if not pexp:
                    plo, phi = 0, pwidth - 1
                n = phi - plo + 1
                if rhs in ("true", "false"):
                    src = ("const", 1 if rhs == "true" else 0)
                    for k in range(n):
                        self._connect(pin in p_out, pidx, pin, plo + k, src)
                    continue
                wname, wlo, whi, wexp = _parse_pin_ref(rhs)
                if not wexp:
                    wlo, whi = 0, n - 1
                if whi - wlo + 1 != n:
                    raise ValueError("%s: width mismatch on %s=%s" %
                                     (cdef.name, pin, rhs))
                for k in range(n):
                    self._connect(pin in p_out, pidx, pin, plo + k,
                                  ("wire", wname, wlo + k))
            self.parts.append((inst, sinks if False else None))
            self.parts[pidx] = (inst, sinks)
        # second pass done inside _connect via self._cur
        self._finalize()

    # Two-phase trickery avoided: _connect stores into current structures.
    def _connect(self, is_output, pidx, pin, pbit, src):
        if is_output:
            if src[0] == "const":
                raise ValueError("output pin tied to constant")
            _, wname, wbit = src
            self.drivers[(wname, wbit)] = (pidx, pin, pbit)
        else:
            self._cur_sinks[(pin, pbit)] = src

    def _finalize(self):
        pass

    def eval(self, inputs):
        cache = {}

        def part_out(pidx):
            if pidx in cache:
                return cache[pidx]
            cache[pidx] = None  # cycle marker
            inst, sinks = self.parts[pidx]
            invals = {}
            for (pin, pbit), src in sinks.items():
                if src[0] == "const":
                    v = src[1]
                else:
                    v = wire_bit(src[1], src[2])
                invals[pin] = invals.get(pin, 0) | (v << pbit)
            res = inst.eval(invals)
            cache[pidx] = res
            return res

        def wire_bit(wname, bit):
            if wname in self.cdef.inputs:
                return (inputs.get(wname, 0) >> bit) & 1
            drv = self.drivers.get((wname, bit))
            if drv is None:
                return 0
            pidx, pin, pbit = drv
            return (part_out(pidx).get(pin, 0) >> pbit) & 1

        outs = {}
        for pin, width in self.cdef.outputs.items():
            v = 0
            for b in range(width):
                v |= wire_bit(pin, b) << b
            outs[pin] = v
        return outs

    def commit(self):
        for inst, _ in self.parts:
            inst.commit()


