"""Minimal Hack assembler and CPU emulator for verifying .asm programs."""

import re

PREDEFINED = {"R%d" % i: i for i in range(16)}
PREDEFINED.update({"SP": 0, "LCL": 1, "ARG": 2, "THIS": 3, "THAT": 4,
                   "SCREEN": 16384, "KBD": 24576})

COMP = {
    "0": 0b0101010, "1": 0b0111111, "-1": 0b0111010, "D": 0b0001100,
    "A": 0b0110000, "!D": 0b0001101, "!A": 0b0110001, "-D": 0b0001111,
    "-A": 0b0110011, "D+1": 0b0011111, "A+1": 0b0110111, "D-1": 0b0001110,
    "A-1": 0b0110010, "D+A": 0b0000010, "D-A": 0b0010011, "A-D": 0b0000111,
    "D&A": 0b0000000, "D|A": 0b0010101,
    "M": 0b1110000, "!M": 0b1110001, "-M": 0b1110011, "M+1": 0b1110111,
    "M-1": 0b1110010, "D+M": 0b1000010, "D-M": 0b1010011, "M-D": 0b1000111,
    "D&M": 0b1000000, "D|M": 0b1010101,
}
DEST = {"": 0, "M": 1, "D": 2, "MD": 3, "A": 4, "AM": 5, "AD": 6, "AMD": 7}
JUMP = {"": 0, "JGT": 1, "JEQ": 2, "JGE": 3, "JLT": 4, "JNE": 5, "JLE": 6,
        "JMP": 7}


def assemble(src):
    lines = []
    for raw in src.splitlines():
        line = re.sub(r"//.*", "", raw).strip()
        if line:
            lines.append(line)
    # pass 1: labels
    symbols = dict(PREDEFINED)
    rom = 0
    for line in lines:
        m = re.match(r"^\((\w+)\)$", line)
        if m:
            symbols[m.group(1)] = rom
        else:
            rom += 1
    # pass 2: code
    prog = []
    next_var = 16
    for line in lines:
        if line.startswith("("):
            continue
        if line.startswith("@"):
            sym = line[1:]
            if sym.isdigit():
                addr = int(sym)
            else:
                if sym not in symbols:
                    symbols[sym] = next_var
                    next_var += 1
                addr = symbols[sym]
            assert 0 <= addr < 32768, "A-value out of range: " + line
            prog.append(addr)
        else:
            m = re.match(r"^(?:([ADM]+)=)?([01ADM!\-+&|]+)(?:;(\w+))?$", line)
            assert m, "bad C-instruction: " + line
            dest, comp, jump = m.group(1) or "", m.group(2), m.group(3) or ""
            assert comp in COMP, "bad comp: " + comp
            assert dest in DEST, "bad dest: " + dest
            assert jump in JUMP, "bad jump: " + jump
            prog.append(0b111 << 13 | COMP[comp] << 6 |
                        DEST[dest] << 3 | JUMP[jump])
    return prog


class Emulator:
    """Hack CPU with flat 32K RAM; ram[24576] mirrors the keyboard."""

    def __init__(self, program):
        self.rom = program
        self.ram = [0] * 32768
        self.A = 0
        self.D = 0
        self.pc = 0
        self.kbd = 0

    def read_mem(self, addr):
        if addr == 24576:
            return self.kbd
        return self.ram[addr]

    def step(self):
        instr = self.rom[self.pc] if self.pc < len(self.rom) else 0
        if not (instr >> 15):
            self.A = instr
            self.pc += 1
            return
        a = (instr >> 12) & 1
        zx, nx = (instr >> 11) & 1, (instr >> 10) & 1
        zy, ny = (instr >> 9) & 1, (instr >> 8) & 1
        f, no = (instr >> 7) & 1, (instr >> 6) & 1
        d1, d2, d3 = (instr >> 5) & 1, (instr >> 4) & 1, (instr >> 3) & 1
        j1, j2, j3 = (instr >> 2) & 1, (instr >> 1) & 1, instr & 1

        x, y = self.D, self.read_mem(self.A) if a else self.A
        if zx:
            x = 0
        if nx:
            x ^= 0xFFFF
        if zy:
            y = 0
        if ny:
            y ^= 0xFFFF
        out = ((x + y) & 0xFFFF) if f else (x & y)
        if no:
            out ^= 0xFFFF
        zr = 1 if out == 0 else 0
        ng = (out >> 15) & 1
        pos = 1 if (not zr and not ng) else 0

        old_a = self.A
        if d1:
            self.A = out
        if d2:
            self.D = out
        if d3:
            self.ram[old_a & 0x7FFF] = out
        jump = (j1 and pos) or (j2 and zr) or (j3 and ng)
        self.pc = old_a if jump else self.pc + 1

    def run(self, cycles):
        for _ in range(cycles):
            self.step()

