class ChipLoader:
    def __init__(self, dirs):
        self.dirs = dirs
        self.defs = {}
        self.deps_cache = {}

    def get_def(self, name):
        if name in self.defs:
            return self.defs[name]
        for d in self.dirs:
            p = os.path.join(d, name + ".hdl")
            if os.path.exists(p):
                cdef = parse_hdl(p)
                self.defs[name] = cdef
                return cdef
        self.defs[name] = None
        return None

    def instantiate(self, name):
        cdef = self.get_def(name)
        if cdef is None:
            if name not in BUILTIN_PINS:
                raise ValueError("no HDL or builtin for chip " + name)
            return Builtin(name)
        return Composite(cdef, self)

    @staticmethod
    def is_clocked_inst(inst):
        if isinstance(inst, Builtin):
            return not inst.comb
        return inst.clocked

    def out_input_deps(self, comp):
        """Input pins of a clocked composite chip that its outputs may
        combinationally depend on (paths not crossing a clocked part)."""
        if comp.name in self.deps_cache:
            return self.deps_cache[comp.name]
        deps = set()
        seen = set()
        stack = []
        for pin, width in comp.cdef.outputs.items():
            for b in range(width):
                stack.append((pin, b))
        visited_parts = set()
        while stack:
            wb = stack.pop()
            if wb in seen:
                continue
            seen.add(wb)
            wname, bit = wb
            if wname in comp.cdef.inputs:
                deps.add(wname)
                continue
            drv = comp.drivers.get(wb)
            if drv is None:
                continue
            pidx, _, _ = drv
            if pidx in visited_parts:
                continue
            visited_parts.add(pidx)
            inst, sinks = comp.parts[pidx]
            if self.is_clocked_inst(inst):
                continue  # output is state-based; stop tracing
            for (pin, pbit), src in sinks.items():
                if src[0] == "wire":
                    stack.append((src[1], src[2]))
        self.deps_cache[comp.name] = deps
        return deps

