def find_inst(inst, name):
    """First sub-instance (any depth) whose chip name matches."""
    stack = [inst]
    while stack:
        cur = stack.pop()
        if cur.name == name:
            return cur
        if isinstance(cur, Composite):
            stack.extend(p[0] for p in cur.parts)
    return None


