def part_pin(pidx, opin):
    """Value of one output pin of a part (demand-driven)."""
    inst, sinks = self.parts[pidx]
    if isinstance(inst, Composite) and inst.clocked:
        # Per-pin evaluation: gather only the inputs this output
        # pin combinationally depends on, so state-based outputs
        # (pc, register outputs, ...) never pull in data inputs
        # and clocked feedback loops resolve correctly.
        key = (pidx, opin)
        if key in pin_cache:
            res = pin_cache[key]
            if res is None:
                raise ValueError("%s: combinational loop detected" %
                                 self.name)
            return res
        pin_cache[key] = None
        deps = self.loader.out_input_deps(inst).get(opin, set())
        res = inst.eval(gather(sinks, deps)).get(opin, 0)
        pin_cache[key] = res
        return res
    if pidx in whole:
        res = whole[pidx]
        if res is None:
            raise ValueError("%s: combinational loop detected" %
                             self.name)
        return res.get(opin, 0)
    whole[pidx] = None
    if isinstance(inst, Builtin) and not inst.comb:
        res = inst.eval(gather(sinks,
                               Builtin.OUT_INPUTS.get(inst.name, ())))
    else:
        res = inst.eval(gather(sinks))
    whole[pidx] = res
    return res.get(opin, 0)

def wire_bit(wname, bit):
    if wname in self.cdef.inputs:
        return (inputs.get(wname, 0) >> bit) & 1
    drv = self.drivers.get((wname, bit))
    if drv is None:
        return 0
    pidx, pin, pbit = drv
    return (part_pin(pidx, pin) >> pbit) & 1

return part_pin, wire_bit

